// 42일/7일 컷오프 날짜 계산
const today = new Date()
const todayStr = today.toISOString().split('T')[0]

const sevenDaysAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000)
  .toISOString().split('T')[0]
const fortyTwoDaysAgo = new Date(today.getTime() - 42 * 24 * 60 * 60 * 1000)
  .toISOString().split('T')[0]

return [{
  json: {
    today: todayStr,
    sevenDaysAgo,
    fortyTwoDaysAgo,
    spreadsheetId: 'YOUR_ICEPOP_SHEET_ID',
    sheet1: '1호점_상품별',
    sheet2: '2호점_상품별'
  }
}]

// ============================================
// gviz 응답 파싱 + 매장별 × 상품명별 집계
// ============================================

const meta = $('날짜 계산').first().json
const sevenDaysAgo = meta.sevenDaysAgo
const fortyTwoDaysAgo = meta.fortyTwoDaysAgo

// gviz 응답 파싱 (wrapper 제거)
function parseGvizResponse(raw) {
  // /*O_o*/google.visualization.Query.setResponse({...});
  const match = raw.match(/google\.visualization\.Query\.setResponse\((.*)\);?\s*$/s)
  if (!match) {
    throw new Error('gviz 응답 파싱 실패')
  }
  return JSON.parse(match[1])
}

// HTTP Request 노드 응답은 .data 필드에 텍스트로 들어옴 (responseFormat: text)
const raw1 = $('1호점 gviz 조회').first().json.data
const raw2 = $('2호점 gviz 조회').first().json.data

const parsed1 = parseGvizResponse(raw1)
const parsed2 = parseGvizResponse(raw2)

// rows → 데이터 배열 변환
// SELECT A,E,F → cols: [매출일자, 상품명, 판매수량]
function rowsToData(parsed) {
  return parsed.table.rows.map(row => ({
    매출일자: row.c[0]?.v || '',
    상품명: row.c[1]?.v || '',
    판매수량: parseInt(row.c[2]?.v) || 0
  }))
}

const data1 = rowsToData(parsed1)
const data2 = rowsToData(parsed2)

// === 집계 ===
const aggregate = {}

function process(data, store) {
  for (const row of data) {
    const date = row.매출일자
    const name = row.상품명
    const qty = row.판매수량

    if (!date || !name) continue

    const is7Days = date >= sevenDaysAgo
    const is42Days = date >= fortyTwoDaysAgo

    if (!is42Days) continue

    if (!aggregate[name]) {
      aggregate[name] = {
        상품명: name,
        '1호점_7일': 0,
        '2호점_7일': 0,
        '7일_총합': 0,
        '1호점_42일': 0,
        '2호점_42일': 0,
        '42일_총합': 0
      }
    }

    const agg = aggregate[name]

    if (is7Days) {
      agg[`${store}_7일`] += qty
      agg['7일_총합'] += qty
    }
    agg[`${store}_42일`] += qty
    agg['42일_총합'] += qty
  }
}

process(data1, '1호점')
process(data2, '2호점')

// 결과 정리 + 정렬 (상품명 가나다 순)
const results = Object.values(aggregate)
  .filter(a => a['42일_총합'] > 0)  // 42일 판매 0이면 제외
  .sort((a, b) => a.상품명.localeCompare(b.상품명, 'ko'))

return [{
  json: {
    aggregated: results,
    stats: {
      총_상품수: results.length,
      sevenDaysAgo,
      fortyTwoDaysAgo,
      raw1_rows: data1.length,
      raw2_rows: data2.length
    }
  }
}]
